class QuerySafetyNameFactsTest {
	private static final SimpleValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();

	@Test
	void cheapSafetyFactsDoNotMaterializeBindingNameStorage() {
		Extension query = nameRichQuery();
		QueryEvaluationUtility.QuerySafetySnapshot snapshot = QueryEvaluationUtility.querySafetySnapshot(query);

		assertThat(snapshot.isRepeatable(query)).isTrue();
		assertThat(snapshot.mayRaiseQueryFatalError(query)).isFalse();
		assertThat(snapshot.usesMappingParameterizedEvaluation(query)).isFalse();
		assertThat(snapshot.containsLateral(query)).isFalse();
		assertThat(snapshot.containsExtension(query)).isTrue();
		assertThat(snapshot.retainedNameFactStorageUnits())
				.as("cheap safety flags do not need interned binding-name facts")
				.isZero();

		assertThat(snapshot.permitsBindingInjection(query, Set.of("filterRead"))).isFalse();
		assertThat(snapshot.permitsBindingInjection(query, Set.of("extensionTarget"))).isFalse();
		assertThat(snapshot.permitsBindingInjection(query, Set.of("subject"))).isTrue();
		assertThat(snapshot.retainedNameFactStorageUnits()).isPositive();
	}

	@Test
	void publicSnapshotRetainsCapturedNameFactsAfterTheTreeChangesBeforeTheirFirstRead() {
		Extension query = nameRichQuery();
		Filter filter = (Filter) query.getArg();
		QueryEvaluationUtility.QuerySafetySnapshot original = QueryEvaluationUtility.querySafetySnapshot(query);

		filter.setCondition(new Bound(Var.of("newFilterRead")));
		query.getElements().get(0).setName("newExtensionTarget");
		query.setArg(new Join(filter, statementPattern("addedSubject", "addedPredicate", "addedObject")));

		assertThat(original.permitsBindingInjection(query, Set.of("filterRead"))).isFalse();
		assertThat(original.permitsBindingInjection(query, Set.of("newFilterRead"))).isTrue();
		assertThat(original.permitsBindingInjection(query, Set.of("extensionTarget"))).isFalse();
		assertThat(original.permitsBindingInjection(query, Set.of("newExtensionTarget"))).isTrue();

		QueryEvaluationUtility.QuerySafetySnapshot updated = QueryEvaluationUtility.querySafetySnapshot(query);
		assertThat(updated.permitsBindingInjection(query, Set.of("filterRead"))).isTrue();
		assertThat(updated.permitsBindingInjection(query, Set.of("newFilterRead"))).isFalse();
		assertThat(updated.permitsBindingInjection(query, Set.of("extensionTarget"))).isTrue();
		assertThat(updated.permitsBindingInjection(query, Set.of("newExtensionTarget"))).isFalse();
		assertThat(updated.permitsBindingInjection(query, Set.of("addedSubject"))).isTrue();
	}

	@Test
	void refreshFromUpdatesNameFactsThroughNestedOperatorsBeforeAndAfterTheirFirstRead() {
		BindingSetAssignment leftValues = values("guard", "afterDemand", "leftCondition");
		BindingSetAssignment rightValues = values("guard", "afterDemand", "leftCondition");
		Union union = new Union(leftValues, rightValues);
		Filter guardFilter = new Filter(union, new Bound(Var.of("guard")));
		Filter afterDemandFilter = new Filter(guardFilter, new Bound(Var.of("afterDemand")));
		Extension extension = new Extension(afterDemandFilter, extensionElement("target"));
		Join join = new Join(extension, statementPattern("joinedSubject", "joinedPredicate", "joinedObject"));
		LeftJoin root = new LeftJoin(join,
				statementPattern("optionalSubject", "optionalPredicate", "optionalObject"),
				new Bound(Var.of("leftCondition")));
		QueryEvaluationUtility.QuerySafetySnapshot snapshot = QueryEvaluationUtility.querySafetySnapshot(root);

		assertCheapFlags(root, snapshot);
		// Change only VALUE bindings and an extension target before the first binding-injection query.
		rightValues.setBindingNames(Set.of("afterDemand", "leftCondition"));
		extension.getElements().get(0).setName("newTarget");
		snapshot.refreshFrom(rightValues);
		snapshot.refreshFrom(extension);
		assertCheapFlags(root, snapshot);

		assertThat(snapshot.permitsBindingInjection(root, Set.of("guard"))).isFalse();
		assertThat(snapshot.permitsBindingInjection(root, Set.of("afterDemand"))).isTrue();
		assertThat(snapshot.permitsBindingInjection(root, Set.of("target"))).isTrue();
		assertThat(snapshot.permitsBindingInjection(root, Set.of("newTarget"))).isFalse();

		// Repeat the name-only changes after the name facts have already been materialized.
		rightValues.setBindingNames(Set.of("guard", "leftCondition"));
		extension.getElements().get(0).setName("target");
		snapshot.refreshFrom(rightValues);
		snapshot.refreshFrom(extension);
		assertThat(snapshot.permitsBindingInjection(root, Set.of("guard"))).isTrue();
		assertThat(snapshot.permitsBindingInjection(root, Set.of("afterDemand"))).isFalse();
		assertThat(snapshot.permitsBindingInjection(root, Set.of("newTarget"))).isTrue();
		assertThat(snapshot.permitsBindingInjection(root, Set.of("target"))).isFalse();

		guardFilter.setCondition(new Bound(Var.of("newFilterRead")));
		snapshot.refreshFrom(guardFilter);
		assertThat(snapshot.permitsBindingInjection(root, Set.of("guard"))).isTrue();
		assertThat(snapshot.permitsBindingInjection(root, Set.of("newFilterRead"))).isFalse();
		assertCheapFlags(root, snapshot);
	}

	@Test
	void concurrentFirstBindingNameDemandKeepsDistinctSubtreeFactsIsolated() throws Exception {
		Extension left = namedFilter("leftRead", "leftTarget");
		Extension right = namedFilter("rightRead", "rightTarget");
		Join root = new Join(left, right);
		QueryEvaluationUtility.QuerySafetySnapshot snapshot = QueryEvaluationUtility.querySafetySnapshot(root);
		CyclicBarrier firstDemand = new CyclicBarrier(2);

		try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
			Future<List<Boolean>> leftResult = executor.submit(() -> {
				awaitFirstDemand(firstDemand);
				return List.of(
						snapshot.permitsBindingInjection(left, Set.of("leftRead")),
						snapshot.permitsBindingInjection(left, Set.of("rightRead")));
			});
			Future<List<Boolean>> rightResult = executor.submit(() -> {
				awaitFirstDemand(firstDemand);
				return List.of(
						snapshot.permitsBindingInjection(right, Set.of("rightRead")),
						snapshot.permitsBindingInjection(right, Set.of("leftRead")));
			});

			List<List<Boolean>> results = new ArrayList<>();
			List<Throwable> failures = new ArrayList<>();
			collectFuture(leftResult, results, failures);
			collectFuture(rightResult, results, failures);

			assertThat(failures).as("concurrent name-fact materialization completes without worker failures").isEmpty();
			assertThat(results).containsExactly(List.of(false, true), List.of(false, true));
		}
	}

	private static void assertCheapFlags(TupleExpr root, QueryEvaluationUtility.QuerySafetySnapshot snapshot) {
		assertThat(snapshot.isRepeatable(root)).isTrue();
		assertThat(snapshot.mayRaiseQueryFatalError(root)).isFalse();
		assertThat(snapshot.usesMappingParameterizedEvaluation(root)).isFalse();
		assertThat(snapshot.containsLateral(root)).isFalse();
		assertThat(snapshot.containsExtension(root)).isTrue();
	}

	private static Extension nameRichQuery() {
		Filter filter = new Filter(statementPattern("subject", "predicate", "object"),
				new Bound(Var.of("filterRead")));
		return new Extension(filter, extensionElement("extensionTarget"));
	}

	private static Extension namedFilter(String readName, String targetName) {
		Filter filter = new Filter(statementPattern(readName + "Subject", readName + "Predicate", readName + "Object"),
				new Bound(Var.of(readName)));
		return new Extension(filter, extensionElement(targetName));
	}

	private static void awaitFirstDemand(CyclicBarrier barrier) {
		try {
			barrier.await(10, TimeUnit.SECONDS);
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted while coordinating the first name-fact demand", e);
		} catch (BrokenBarrierException | TimeoutException e) {
			throw new AssertionError("both subtrees must reach the first name-fact demand", e);
		}
	}

	private static void collectFuture(Future<List<Boolean>> future, List<List<Boolean>> results,
			List<Throwable> failures) {
		try {
			results.add(future.get(12, TimeUnit.SECONDS));
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			future.cancel(true);
			failures.add(e);
		} catch (ExecutionException | TimeoutException e) {
			future.cancel(true);
			failures.add(e instanceof ExecutionException ? e.getCause() : e);
		}
	}

	private static ExtensionElem extensionElement(String target) {
		return new ExtensionElem(new ValueConstant(VALUE_FACTORY.createLiteral("value")), target);
	}

	private static BindingSetAssignment values(String... names) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(names));
		return assignment;
	}

	private static StatementPattern statementPattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of(predicate), Var.of(object));
	}
}
